#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y) {
        assert(x > 0 && y > 0 && x + y < n);
        ops.push_back({x, y});
        vector<int> np;
        for(int i = n-y; i < n; i++) np.push_back(p[i]);
        for(int i = x; i < n-y; i++) np.push_back(p[i]);
        for(int i = 0; i < x; i++) np.push_back(p[i]);
        p = np;
    };

    for(int k = 0; k < n-1; k++) {
        int pos = -1;
        for(int i = k; i < n; i++) if(p[i] == k+1) { pos = i; break; }
        if(pos == k) continue;

        int remaining = n - k; // effective size of unsorted part (positions k..n-1)

        // Step 1: Move element to position n-1
        if(pos != n-1) {
            if(pos == 0) {
                // x=1, y=n-2: moves pos 0 to end (pos n-1)
                if(n > 2) { doOp(1, n-2); pos = n-1; }
            } else if(pos < n-1) {
                // x=pos, y=n-1-pos => x+y=n-1<n, valid since pos>0 and n-1-pos>0
                doOp(pos, n-1-pos);
                // element was at pos, now it's at position n-1-pos (within suffix block, last element maps to y-1=n-1-pos)
                // Wait: element at pos is first of middle. suffix=[pos+1..n-1], middle=[pos], prefix=[0..pos-1]
                // Result: suffix + middle + prefix. Element at position (n-1-pos).
                pos = n-1-pos;
                if(pos != n-1 && pos > 0 && pos < n-1) {
                    doOp(pos, n-1-pos);
                    pos = n-1-pos;
                }
            }
        }

        // Step 2: Move from n-1 to k
        if(pos == n-1 && k < n-1) {
            int y = k + 1;
            int x = 1;
            if(k == 0) { if(n > 2) doOp(1, 1); }
            else if(x + y < n) doOp(x, y);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
